export type Post = { id: number; title: string; body: string };

const API_BASE_URL = "https://jsonplaceholder.typicode.com";

export async function getPosts(signal?: AbortSignal): Promise<Post[]> {
  const response = await fetch(`${API_BASE_URL}/posts`, { signal });
  if (!response.ok) {
    throw new Error(`Could not load posts: HTTP ${response.status}`);
  }
  return (await response.json()) as Post[];
}

import { useCallback, useEffect, useState } from "react";
import { getPosts, type Post } from "./postsApi";

type LoadState<T> =
  | { status: "loading" }
  | { status: "success"; data: T }
  | { status: "error"; message: string };

export function usePosts() {
  const [state, setState] = useState<LoadState<Post[]>>({ status: "loading" });
  const [reloadKey, setReloadKey] = useState(0);

  const reload = useCallback(() => setReloadKey((key) => key + 1), []);

  useEffect(() => {
    const controller = new AbortController();
    setState({ status: "loading" });
    getPosts(controller.signal)
      .then((data) => setState({ status: "success", data }))
      .catch((error: unknown) => {
        if (controller.signal.aborted) return;
        setState({ status: "error", message: "Could not load posts" });
      });
    return () => controller.abort();
  }, [reloadKey]);

  return { state, reload };
}

